## Why This Is Asked
This question tests understanding of prefix-based searching using a practical, lightweight data structure. It combines Trie fundamentals with per-node augmentation to enable fast prefix queries in real time—useful in autocomplete systems, IP routing, and spell checking.

## Key Concepts
- **Trie structure**: Each node contains 26 children (one per letter) and maintains a pass counter representing how many words pass through that node
- **insert operation**: O(m) time, where m is word length; creates nodes as needed and increments pass at each node visited
- **count_with_prefix operation**: O(k) time, where k is prefix length; traverses to the prefix node and returns its pass counter
- **Handling duplicates**: Pass counters naturally accumulate, so duplicate insertions simply increment the counter without special handling

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Array(26).fill(null);
    this.pass = 0;
    this.isWord = false;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    for (const char of word) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.next[idx]) node.next[idx] = new TrieNode();
      node.pass++;
      node = node.next[idx];
    }
    node.pass++;
    node.isWord = true;
  }

  countWithPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      const idx = char.charCodeAt(0) - 97;
      if (!node.next[idx]) return 0;
      node = node.next[idx];
    }
    return node.pass;
  }
}

// Example usage
const trie = new Trie();
['cat', 'car', 'cart', 'dog', 'dot'].forEach(w => trie.insert(w));
console.log(trie.countWithPrefix('ca')); // 3
console.log(trie.countWithPrefix('car')); // 1
console.log(trie.countWithPrefix('d')); // 2
console.log(trie.countWithPrefix('do')); // 2
```

## Why This Is Asked

Tests algorithmic depth and practical handling of worst-case quicksort behavior.

## Key Concepts

- Introsort: hybrid of quicksort and heapsort with depth guard
- Median-of-three pivot to avoid pathological inputs
- In-place partition and recursion depth management
- Complexity: O(n log n) average and worst-case; O(log n) stack space

## Code Example

```javascript
// Introsort skeleton in JS
function introsort(arr) {
  const n = arr.length;
  if (n <= 1) return;
  const maxDepth = Math.floor(2 * Math.log2(n));
  function swap(i, j) { const t = arr[i]; arr[i] = arr[j]; arr[j] = t; }
  function medianOfThree(lo, mid, hi) {
    if (arr[lo] > arr[mid]) swap(lo, mid);
    if (arr[lo] > arr[hi]) swap(lo, hi);
    if (arr[mid] > arr[hi]) swap(mid, hi);
    return mid;
  }
  function partition(lo, hi) {
    const mid = Math.floor((lo + hi) / 2);
    const m = medianOfThree(lo, mid, hi);
    swap(m, hi);
    const pivot = arr[hi];
    let i = lo;
    for (let j = lo; j < hi; j++) {
      if (arr[j] <= pivot) { swap(i, j); i++; }
    }
    swap(i, hi);
    return i;
  }
  function heapSort(lo, hi) {
    const n = hi - lo + 1;
    function heapify(i, size) {
      while (true) {
        const l = 2 * i + 1;
        const r = l + 1;
        let largest = i;
        if (l < size && arr[lo + l] > arr[lo + largest]) largest = l;
        if (r < size && arr[lo + r] > arr[lo + largest]) largest = r;
        if (largest !== i) { swap(lo + i, lo + largest); i = largest; } else break;
      }
    }
    for (let i = Math.floor(n / 2) - 1; i >= 0; i--) heapify(i, n);
    for (let end = n - 1; end > 0; end--) {
      swap(lo, lo + end);
      heapify(0, end);
    }
  }
  function insertionSort(lo, hi) {
    for (let i = lo + 1; i <= hi; i++) {
      const key = arr[i];
      let j = i - 1;
      while (j >= lo && arr[j] > key) { arr[j + 1] = arr[j]; j--; }
      arr[j + 1] = key;
    }
  }
  function quickSort(lo, hi, depth) {
    const size = hi - lo + 1;
    if (size <= 16) { insertionSort(lo, hi); return; }
    if (depth <= 0) { heapSort(lo, hi); return; }
    const p = partition(lo, hi);
    quickSort(lo, p - 1, depth - 1);
    quickSort(p + 1, hi, depth - 1);
  }
  quickSort(0, n - 1, maxDepth);
}
```

